mapper.update:
UPDATE search_area
SET status = #{status},
    geometry = ST_GeomFromEWKT(#{geometry,typeHandler=com.surimap.config.mybatis.JtsGeometryTypeHandler}),
    version = #{version},
    updated_at = #{updatedAt}
WHERE id = #{id,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}

mapper.select:
SELECT


WHERE area.id = #{id,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
GROUP BY area.id, op.incident_id

SELECT
WHERE op.incident_id = #{incidentId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
GROUP BY area.id, op.incident_id ORDER BY area.operational_period_id ASC, area.status ASC, area.updated_at ASC, area.id ASC

SELECT


WHERE area.operational_period_id = #{opId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}

  AND area.status IN

    #{status}



  AND area.status != 'CANCELLED'


  AND area.version >= #{filters.minVersion}


  AND area.updated_at > #{filters.updatedAfter}


  AND ST_Intersects(
      area.geometry,
      ST_MakeEnvelope(
          #{filters.bbox[0]},
          #{filters.bbox[1]},
          #{filters.bbox[2]},
          #{filters.bbox[3]},
          4326
      )
  )

GROUP BY area.id, op.incident_id
ORDER BY area.operational_period_id ASC, area.status ASC, area.updated_at ASC, area.id ASC
